    Counts lowercase words, ignoring punctuation (a word is a run of letters, 
    accented letters included).
    """
    counts = {}
    current_word_chars = []

    for char in text:
        if char.isalpha():
            current_word_chars.append(char)
        else:
            if current_word_chars:
                word = "".join(current_word_chars).lower()
                counts[word] = counts.get(word, 0) + 1
                current_word_chars = []

    # Handle the final word if it exists at the end of the text
    if current_word_chars:
        word = "".join(current_word_chars).lower()
        counts[word] = counts.get(word, 0) + 1

