import math

def compact(n: int) -> str:
    if n < 0:
        raise ValueError("Input must be a non-negative integer")

    # Define units and their corresponding scale factors (powers of 1000)
    units = [
        (10**9, 'bi'),
        (10**6, 'mi'),
        (10**3, 'mil'),
    ]

    # Handle numbers less than 1000 (no unit needed)
    if n < 1000:
        return str(n)

    for scale, unit in units:
        if n >= scale:
            # Calculate the value relative to the current unit
            val = n / scale

            # Implement custom round half up to one decimal place
            # This logic ensures that 0.5 rounds up to the next tenth.
            rounded_val = math.floor(val * 10 + 0.5) / 10

            # Format the string: use comma as decimal separator
            # If the rounded value is exactly X.0 (e.g., 2.0), we must display it as '2'
            if rounded_val == math.floor(rounded_val):
                formatted_val = str(int(rounded_val))
            else:
                formatted_val = f"{int(rounded_val[:-1])},{int(rounded_val[-1])}"

            return f"{formatted_val} {unit}"

    # Fallback, though n >= 1000 should be caught by the loop
    return str(n)
