def wrap(text: str, width: int) -> list[str]:
    if not text or not text.strip():
        return []

    # 1. Tokenization: Split text into words or chunks of words
    words = text.split()
    tokens = []
    for word in words:
        if len(word) <= width:
            tokens.append(word)
        else:
            # If word is too long, cut it into pieces of size 'width'
            for i in range(0, len(word), width):
                tokens.append(word[i:i + width])

    if not tokens:
        return []

    # 2. Line construction (Greedy)
    lines = []
    current_line_tokens = []

    for token in tokens:
        # Calculate length required if this token is added
        if not current_line_tokens:
            new_line_len = len(token)
        else:
            # Length calculation: current length + space + token length
            new_line_len = len(" ".join(current_line_tokens)) + 1 + len(token)

        if new_line_len <= width:
            current_line_tokens.append(token)
        else:
            # The token doesn't fit on the current line
            # Finalize the previous line
            lines.append(" ".join(current_line_tokens))
            # Start a new line with the current token
            current_line_tokens = [token]

    # Add the last line if it has content
    if current_line_tokens:
        lines.append(" ".join(current_line_tokens))

    return lines
