import math

def is_not_prime(n):
    """
    Identifies if a number n is a non-prime number (i.e., composite or less than 2).
    Returns True if n is non-prime, False if n is prime.
    """
    if n <= 1:
        return True
    if n == 2:
        return False
    if n % 2 == 0:
        return True

    limit = int(math.sqrt(n))
    for i in range(3, limit + 1, 2):
        if n % i == 0:
            return True

    return False
