import heapq

def heap_queue_largest(numbers, n):
    """
    Finds the n largest integers from a list of numbers using a min-heap.

    The time complexity is O(M log N), where M is the length of numbers 
    and N is the value of n.
    """
    if n <= 0:
        return []
    if n >= len(numbers):
        return sorted(numbers, reverse=True)

    min_heap = []

    for num in numbers:
        if len(min_heap) < n:
            heapq.heappush(min_heap, num)
        elif num > min_heap[0]:
            # Pop the smallest element and push the larger current number
            heapq.heapreplace(min_heap, num)

    # The min_heap now contains the n largest elements.
    # Extract them and reverse to return them in descending order.
    return sorted(min_heap, reverse=True)
