from datetime import date, timedelta
from typing import Set

def add_business_days(d: date, n: int, holidays: Set[date]) -> date:
    """
    Moves n business days (Monday to Friday, not in holidays) from d; 
    n may be negative. d itself never counts as one of the n days. 
    With n == 0, return d if it is a business day, otherwise the next business day.
    """

    def is_business_day(dt: date) -> bool:
        # Monday=0, Sunday=6. Business days are 0-4.
        return dt.weekday() < 5 and dt not in holidays

    # Handle n=0 case first
    if n == 0:
        if is_business_day(d):
            return d
        else:
            # Find the next business day if d is not one
            current_date = d
            while not is_business_day(current_date):
                current_date += timedelta(days=1)
            return current_date

    if n > 0:
        # Move forward
        current_date = d
        days_remaining = n
        while days_remaining > 0:
            current_date += timedelta(days=1)
            if is_business_day(current_date):
                days_remaining -= 1
        return current_date
    else:
        # Move backward
        current_date = d
        days_remaining = abs(n)
        while days_remaining > 0:
            current_date -= timedelta(days=1)
            if is_business_day(current_date):
                days_remaining -= 1
        return current_date
