import re

def natural_sorted(names: list[str]) -> list[str]:
    def re_key(text: str) -> list:
        # Split the string into alternating segments of non-digits and digits.
        # The capturing group (\d+) ensures the digits are kept in the list.
        parts = re.split(r'(\d+)', text)

        key_parts = []
        for part in parts:
            if part.isdigit():
                # Convert numeric segments to integers to enable numeric comparison
                key_parts.append(int(part))
            else:
                # Convert text/symbol segments to lowercase for case-insensitive comparison
                key_parts.append(part.lower())
        return key_parts

    return sorted(names, key=re_key)
