from datetime import date, timedelta

def is_business_day(d: date, holidays: set[date]) -> bool:
    """Checks if a date is a business day (Mon-Fri and not a holiday)."""
    # Monday=0, Sunday=6. Business days are 0 through 4.
    return d.weekday() < 5 and d not in holidays

def add_business_days(d: date, n: int, holidays: set[date]) -> date:
    """
    Moves n business days (Monday to Friday, not in holidays) from d; n may be negative.
    d itself never counts as one of the n days.
    """

    # Helper function to find the next business day starting from current_candidate
    def find_next_business_day(current_candidate: date) -> date:
        while True:
            if is_business_day(current_candidate, holidays):
                return current_candidate
            current_candidate += timedelta(days=1)

    # Case n = 0
    if n == 0:
        if is_business_day(d, holidays):
            return d
        else:
            # If d is not a business day, return the next one
            return find_next_business_day(d + timedelta(days=1))

    # Case n > 0 (Moving forward)
    if n > 0:
        count = 0
        current_date = d + timedelta(days=1)
        while count < n:
            if is_business_day(current_date, holidays):
                count += 1
            current_date += timedelta(days=1)
        return current_date

    # Case n < 0 (Moving backward)
    else: # n < 0
        n_abs = -n
        count = 0
        current_date = d - timedelta(days=1)
        while count < n_abs:
            if is_business_day(current_date, holidays):
                count += 1
            current_date -= timedelta(days=1)
        return current_date
