from datetime import datetime
from typing import List, Dict, Any

def latest_by_key(records: List[Dict[str, Any]], key: str) -> List[Dict[str, Any]]:
    """
    Keeps one record per value of record[key]: the one with the latest 'updated_at'.
    On a tie, keeps the record that comes later in the list.
    Returns the records in the order in which each key first appeared.
    """
    best_candidates: Dict[Any, Dict[str, Any]] = {}
    first_appearance: Dict[Any, int] = {}

    # Helper function to parse ISO 8601 strings
    def parse_timestamp(ts_str: str) -> datetime:
        if ts_str.endswith('Z'):
            return datetime.fromisoformat(ts_str.replace('Z', '+00:00'))
        return datetime.fromisoformat(ts_str)

    # Phase 1: Determine the winner for each grouping key
    for i, record in enumerate(records):
        if key not in record:
            continue

        group_value = record[key]
        updated_at = record.get('updated_at')

        if updated_at is None:
            # Cannot determine latest, skip this record
            continue

        current_ts = parse_timestamp(updated_at)

        if group_value not in best_candidates:
            best_candidates[group_value] = {
                'record': record,
                'ts': current_ts,
                'index': i  # Store index for tie-breaking
            }
            first_appearance[group_value] = i
        else:
            existing_best = best_candidates[group_value]

            # Compare: Later timestamp wins. If timestamps are equal, the later index wins.
            is_strictly_later = current_ts > existing_best['ts']
            is_tie = current_ts == existing_best['ts']

            # If it's strictly later OR it's a tie and we are later in the list (i > existing_best['index']), update
            if is_strictly_later or (is_tie and i > existing_best['index']):
                best_candidates[group_value] = {
                    'record': record,
                    'ts': current_ts,
                    'index': i
                }
            # Note: If no update, we keep the existing record. This automatically handles the tie-breaker: 
            # a later index record only replaces an earlier one if it has a strictly later time, 
            # or if it ties (and thus wins by being later).

    # Phase 2: Order the results based on the first appearance of the key

    # Get the list of unique group keys in the order of their first appearance
    ordered_keys = []
    seen_keys = set()
    for record in records:
        if key in record:
            group_value = record[key]
            if group_value in first_appearance:
                # Ensure this key actually ended up as a winner (it should, but safeguard)
                if group_value in best_candidates:
                    if group_value not in seen_keys:
                        ordered_keys.append(group_value)
                        seen_keys.add(group_value)

    # Construct the final list
    result = []
    for k in ordered_keys:
        result.append(best_candidates[k]['record'])

    return result
